// Plays the new-message notification sound (a gym boxing-bell "ding-ding").
// The asset lives at public/sounds/new-message.mp3 and is generated by
// scripts/gen-chat-sound.mjs.

const SRC = '/sounds/new-message.mp3';
// Don't let a burst of incoming messages stack overlapping dings.
const MIN_GAP_MS = 800;

let audio: HTMLAudioElement | null = null;
let lastPlayedAt = 0;

const getAudio = (): HTMLAudioElement | null => {
    if (typeof window === 'undefined') return null;
    if (!audio) {
        audio = new Audio(SRC);
        audio.preload = 'auto';
        audio.volume = 0.5;
    }
    return audio;
};

/** Play the alert for an incoming message. No-op on the server, when throttled,
 *  or when the browser blocks autoplay (rejected play() promise is swallowed). */
export const playNewMessageSound = (): void => {
    const el = getAudio();
    if (!el) return;

    const now = Date.now();
    if (now - lastPlayedAt < MIN_GAP_MS) return;
    lastPlayedAt = now;

    try {
        el.currentTime = 0;
        void el.play().catch(() => {
            /* Autoplay can be blocked until the user interacts — ignore. */
        });
    } catch {
        /* Older Safari can throw synchronously on currentTime — ignore. */
    }
};
